static void RotateLeft(_Rb_tree_node_base*x,_Rb_tree_node_base*&root){_Rb_tree_node_base*y=x->Right;x->Right=y->Left;if(y->Left)y->Left->Parent=x;y->Parent=x->Parent;if(x==root)root=y;else if(x==x->Parent->Left)x->Parent->Left=y;else x->Parent->Right=y;y->Left=x;x->Parent=y;}
static void RotateRight(_Rb_tree_node_base*x,_Rb_tree_node_base*&root){_Rb_tree_node_base*y=x->Left;x->Left=y->Right;if(y->Right)y->Right->Parent=x;y->Parent=x->Parent;if(x==root)root=y;else if(x==x->Parent->Right)x->Parent->Right=y;else x->Parent->Left=y;y->Right=x;x->Parent=y;}
void __cdecl _Rb_tree_rebalance(_Rb_tree_node_base*x,_Rb_tree_node_base*&root){x->Colour=0;while(x!=root&&x->Parent->Colour==0){if(x->Parent==x->Parent->Parent->Left){_Rb_tree_node_base*y=x->Parent->Parent->Right;if(y&&y->Colour==0){x->Parent->Colour=1;y->Colour=1;x->Parent->Parent->Colour=0;x=x->Parent->Parent;}else{if(x==x->Parent->Right){x=x->Parent;RotateLeft(x,root);}x->Parent->Colour=1;x->Parent->Parent->Colour=0;RotateRight(x->Parent->Parent,root);}}else{_Rb_tree_node_base*y=x->Parent->Parent->Left;if(y&&y->Colour==0){x->Parent->Colour=1;y->Colour=1;x->Parent->Parent->Colour=0;x=x->Parent->Parent;}else{if(x==x->Parent->Left){x=x->Parent;RotateRight(x,root);}x->Parent->Colour=1;x->Parent->Parent->Colour=0;RotateLeft(x->Parent->Parent,root);}}}root->Colour=1;}
}
